export interface GpsCoordinate {
  lat: number;
  lng: number;
}

export interface CfsGpsSlot {
  id: string;
  name: string;
  code: string;
  block: string;
  row: string;
  bay: string;
  zoneType:
    | 'Block A (Import)'
    | 'Block B (Export)'
    | 'Block C (Empty Depot)'
    | 'Block D (General Yard)'
    | 'Block F (Trailer Parking)'
    | 'Block H (Reefer Grid)'
    | 'Block I (Customs Shed)';
  cycle?: string;
  status: 'occupied' | 'available' | 'reserved' | 'maintenance' | 'incoming';
  center: GpsCoordinate;
  polygon: GpsCoordinate[];
  truckNumber?: string;
  driverName?: string;
  driverPhone?: string;
  transporter?: string;
  containerNumber?: string;
  isoCode?: string;
  shippingLine?: string;
  cargoType?: 'Dry' | 'Reefer' | 'Hazardous' | 'Empty';
  temperature?: string;
  sealNumber?: string;
  grossWeightKg?: number;
  dwellTime?: string;
  entryTime?: string;
  assignedTask?: string;
  tierLevel?: number;
  maxTiers?: number;
  priority?: boolean;
}

